const $=s=>document.querySelector(s), fmt=(n,d=1)=>n.toLocaleString('es-CO',{maximumFractionDigits:d,minimumFractionDigits:d});
const lessons=[
{title:'Movimiento',heading:'01. Moverse es cambiar de posición.',copy:'La velocidad indica cuánto cambia la posición por segundo. La aceleración indica cuánto cambia la velocidad. Prueba un movimiento que parte del reposo.',params:[['Aceleración',0,4,1,'m/s²',.1],['Tiempo observado',1,6,4,'s',.1]],formula:'x = ½at²',calc:(a,t)=>`x = ${fmt(.5*a*t*t)} m · v = ${fmt(a*t)} m/s`,note:'Movimiento rectilíneo con aceleración constante, x₀ = 0 y v₀ = 0. El ciclo muestra desde t = 0 hasta el tiempo elegido; el resultado corresponde al final.',example:'Al arrancar en bicicleta aumentas tu velocidad. A velocidad constante sigues moviéndote, aunque tu aceleración sea cero.',take:'Moverse no implica acelerar. Acelerar es cambiar la velocidad, incluida su dirección.'},
{title:'Fuerzas y Newton',heading:'02. Más fuerza, más aceleración.',copy:'Una fuerza neta cambia la velocidad. Aplica la misma fuerza a dos masas distintas: el objeto de mayor masa responde con una aceleración menor.',params:[['Fuerza neta',0,20,8,'N',1],['Masa',1,10,2,'kg',.5]],formula:'ΣF = m · a',calc:(f,m)=>`a = ${fmt(f/m)} m/s²`,note:'Superficie horizontal sin fricción. Peso y normal se equilibran; la fuerza indicada es la fuerza horizontal neta. La animación representa 2 s y vuelve al inicio.',example:'Un carrito de mercado vacío acelera más que uno lleno si empujas ambos con la misma fuerza neta.',take:'Sin fuerza neta no cambia la velocidad. Eso no significa necesariamente estar en reposo.'},
{title:'Gravedad',heading:'03. Caer también es acelerar.',copy:'Cerca de la superficie terrestre, la gravedad aumenta la velocidad hacia abajo unos 9,81 m/s cada segundo. Sin aire, todas las masas caen igual desde la misma altura.',params:[['Altura',1,20,10,'m',1],['Masa',1,10,3,'kg',1]],formula:'t = √(2h / g)',calc:(h,m)=>`t = ${fmt(Math.sqrt(2*h/9.81),2)} s · peso = ${fmt(m*9.81)} N`,note:'Caída desde el reposo, g = 9,81 m/s² constante y sin resistencia del aire. Se repite al llegar al suelo. La masa cambia el peso, no el tiempo de caída.',example:'Una bola liviana y una pesada llegan juntas si se sueltan a la vez desde la misma altura en el vacío.',take:'El peso es una fuerza. La masa es una propiedad del objeto.'},
{title:'Fricción',heading:'04. Las superficies se resisten.',copy:'Cuando un objeto ya desliza, la fricción cinética se opone al deslizamiento. Compara el empuje con esa fricción para saber si aumenta o disminuye su rapidez.',params:[['Empuje',0,20,12,'N',1],['Coeficiente μ',0,.8,.2,'',.05]],formula:'f = μN · a = (F − f) / m',calc:(f,u)=>`f = ${fmt(u*2*9.81)} N · a = ${fmt((f-u*2*9.81)/2)} m/s²`,note:'Bloque de 2 kg sobre superficie horizontal, N = mg, velocidad inicial de 4 m/s hacia la derecha. El modelo aplica mientras desliza; se detiene si llega a velocidad cero. No modela el arranque ni la fricción estática.',example:'Un libro que empujas sobre una mesa se frena al soltarlo porque la fricción sigue actuando.',take:'Con rapidez constante puede haber fuerzas: la suma de ellas debe ser cero.'},
{title:'Trabajo y energía',heading:'05. La energía permite producir cambios.',copy:'Una fuerza que actúa a lo largo de un desplazamiento realiza trabajo. Si es la fuerza neta, ese trabajo cambia la energía cinética del objeto.',params:[['Fuerza',1,15,5,'N',1],['Desplazamiento',1,10,4,'m',1]],formula:'W = F · d · cos(θ)',calc:(f,d)=>`W = ${fmt(f*d)} J · ΔEc = ${fmt(f*d)} J`,note:'Fuerza neta constante, paralela al movimiento (θ = 0), masa de 2 kg y salida desde el reposo. Ec = ½mv²; Ep gravitatoria = mgh. Potencia media = trabajo / tiempo.',example:'Al levantar una mochila, tu fuerza hace trabajo y aumenta su energía potencial gravitatoria.',take:'Una fuerza perpendicular al movimiento no realiza trabajo. Energía y trabajo se miden en joules (J).'},
{title:'Cantidad de movimiento',heading:'06. Un movimiento que se transfiere.',copy:'La cantidad de movimiento combina masa y velocidad. En un sistema sin fuerza externa neta, su suma permanece constante, incluso durante un choque.',params:[['Masa del móvil',1,5,2,'kg',.5],['Velocidad inicial',1,6,3,'m/s',.5]],formula:'p = m · v',calc:(m,v)=>`p = ${fmt(m*v)} kg·m/s · vf = ${fmt(m*v/(m+2))} m/s`,note:'Choque completamente inelástico: el móvil se pega a un bloque de 2 kg inicialmente quieto. Se conserva el momento total, pero no la energía cinética. Impulso: F media · Δt = Δp.',example:'Al recibir una pelota, mover las manos hacia atrás aumenta el tiempo de frenado y reduce la fuerza media para el mismo cambio de momento.',take:'La conservación del momento se aplica a la suma de los cuerpos del sistema.'},
{title:'Torque y equilibrio',heading:'07. La distancia también hace fuerza.',copy:'Para girar un objeto importa la fuerza y qué tan lejos del eje la aplicas. La tendencia a producir giro se llama torque o momento de fuerza.',params:[['Fuerza perpendicular',0,20,10,'N',1],['Brazo de palanca',.2,2,1,'m',.1]],formula:'τ = r · F · sin(θ)',calc:(f,r)=>`τ = ${fmt(f*r)} N·m`,note:'Fuerza perpendicular al brazo (θ = 90°). El diagrama muestra el torque aplicado, no la aceleración de giro. Equilibrio estático: ΣF = 0 y Στ = 0.',example:'Es más fácil abrir una puerta empujando cerca de la manija que junto a las bisagras.',take:'Un brazo más largo genera mayor torque con la misma fuerza. N·m expresa torque; aquí no se llama joule.'},
{title:'Oscilaciones',heading:'08. Alejarse. Volver. Repetir.',copy:'Un péndulo intercambia energía potencial y cinética. Cerca de su punto más bajo tiene la mayor rapidez; en los extremos se detiene un instante para regresar.',params:[['Longitud',.5,3,1.5,'m',.1],['Amplitud',2,12,8,'°',1]],formula:'T ≈ 2π √(L / g)',calc:(l,a)=>`Período T ≈ ${fmt(2*Math.PI*Math.sqrt(l/9.81),2)} s`,note:'Péndulo ideal sin rozamiento, g = 9,81 m/s² y ángulos pequeños. La fórmula aproxima el período: tiempo de una ida y vuelta completa.',example:'Un columpio más largo tarda más en completar una oscilación. En este modelo ideal la masa no cambia el período.',take:'La frecuencia es el número de ciclos por segundo: f = 1/T, medida en hertz (Hz).'}];
let current=0,values=[],time=0,last=0,visible=true,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,completed=new Set();try{completed=new Set(JSON.parse(localStorage.getItem('mecanica-progress')||'[]').filter(x=>Number.isInteger(x)&&x>=0&&x<8))}catch{}
const canvas=$('#scene'),ctx=canvas.getContext('2d');let w=800,h=280;
function resize(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);draw()}new ResizeObserver(resize).observe(canvas);
function progress(){$('#progress').textContent=`${completed.size} / 8 conceptos explorados`;$('#progressFill').style.width=completed.size/8*100+'%';$('#complete').textContent=completed.has(current)?'✓ Concepto explorado · Desmarcar':'✓ Marcar como explorado'}
$('.topics').innerHTML=lessons.map((l,i)=>`<button class="topic" role="tab" id="tab${i}" aria-controls="panel" data-i="${i}"><span>${String(i+1).padStart(2,'0')}</span>${l.title}</button>`).join('');
$('.topics').addEventListener('click',e=>{const b=e.target.closest('button');if(b)select(+b.dataset.i)});$('.topics').addEventListener('keydown',e=>{if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?7:(current+(['ArrowRight','ArrowDown'].includes(e.key)?1:7))%8;select(n);$('#tab'+n).focus()}});
function select(i){current=i;time=0;const l=lessons[i];values=l.params.map(p=>p[3]);document.querySelectorAll('.topic').forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1});$('#panel').setAttribute('aria-labelledby','tab'+i);$('#lessonTitle').textContent=l.heading;$('#lessonCopy').textContent=l.copy;$('#note').textContent=l.note;$('#example').textContent=l.example;$('#takeaway').textContent=l.take;$('#formula').textContent=l.formula;canvas.setAttribute('aria-label','Simulación: '+l.title+'. '+l.note);$('#controls').innerHTML=l.params.map((p,j)=>`<label for="slider${j}"><span class="control-label">${p[0]}<output id="out${j}" for="slider${j}"></output></span><input type="range" id="slider${j}" min="${p[1]}" max="${p[2]}" value="${p[3]}" step="${p[5]}" data-j="${j}"></label>`).join('');update();progress()}
function update(){lessons[current].params.forEach((p,j)=>{$('#out'+j).textContent=fmt(values[j],p[5]<1?2:0)+' '+p[4]});$('#result').textContent=lessons[current].calc(...values);draw()}
$('#controls').addEventListener('input',e=>{values[+e.target.dataset.j]=+e.target.value;time=0;update()});$('#complete').onclick=()=>{completed.has(current)?completed.delete(current):completed.add(current);try{localStorage.setItem('mecanica-progress',JSON.stringify([...completed]))}catch{}progress()};
function playLabel(){$('#play').textContent=playing?'Ⅱ Pausar':'▶ Reproducir';$('#play').setAttribute('aria-label',playing?'Pausar animación':'Reproducir animación')}$('#play').onclick=()=>{playing=!playing;playLabel()};$('#reset').onclick=()=>select(current);playLabel();
function line(x,y,x2,y2,color='#8da68b',width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x2,y2);ctx.stroke()}function text(t,x,y,color='#d9e5cd',size=12){ctx.fillStyle=color;ctx.font=`${size}px monospace`;ctx.fillText(t,x,y)}function circle(x,y,r,color='#d9ef66'){ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}function box(x,y,label,color='#d9ef66'){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x-24,y-24,48,48,6);ctx.fill();text(label,x-18,y+4,'#21362b',11)}function arrow(x,y,x2,y2,color='#d9ef66'){line(x,y,x2,y2,color,2);const a=Math.atan2(y2-y,x2-x);line(x2,y2,x2-8*Math.cos(a-.5),y2-8*Math.sin(a-.5),color,2);line(x2,y2,x2-8*Math.cos(a+.5),y2-8*Math.sin(a+.5),color,2)}
function draw(){if(!values.length)return;ctx.clearRect(0,0,w,h);for(let x=20;x<w;x+=25)for(let y=55;y<h;y+=25)circle(x,y,.6,'#456047');const[a,b]=values;const y=h-65,left=48,right=w-48,span=right-left;line(left,y+26,right,y+26,'#708568');
if(current===0){const t=time%b,x=.5*a*t*t,max=72;box(left+x/max*span,y,'●');text(`t = ${fmt(t)} s`,left,80);text('0 m',left,y+47);text('72 m',right-42,y+47);if(a>0)arrow(left+x/max*span+27,y,left+x/max*span+52,y);}
if(current===1){const t=time%2,dist=.5*a/b*t*t;box(left+dist/40*span,y,fmt(b,1));if(a>0)arrow(left+dist/40*span+27,y,left+dist/40*span+27+a*2,y);text(`t = ${fmt(t)} s · échelle: 0–40 m`.replace('échelle','escala'),left,80);text('F neta →',left,105);}
if(current===2){const dur=Math.sqrt(2*a/9.81),t=time%(dur+.5),drop=Math.min(a,.5*9.81*t*t),top=95;line(w/2-70,y+20,w/2+70,y+20);circle(w/2,top+(y-top)*drop/a,12+b*.8);text(`${fmt(a-drop)} m`,w/2+30,top+(y-top)*drop/a);text(`t = ${fmt(Math.min(t,dur),2)} s`,left,80);}
if(current===3){const acc=(a-b*19.62)/2,t0=acc<0?Math.min(3,4/-acc):3,t=Math.min(time%4,t0),x=4*t+.5*acc*t*t,px=left+x/60*span;box(px,y,'2 kg');if(a>0)arrow(px+26,y-7,px+26+a*2,y-7);if(b>0)arrow(px-26,y+7,px-26-b*70,y+7,'#f5b68e');text('Empuje →   ← Fricción',left,80);text(`v = ${fmt(Math.max(0,4+acc*t))} m/s · escala 0–60 m`,left,103);}
if(current===4){const dur=Math.sqrt(4*b/a),t=time%(dur+.6),d=Math.min(b,.25*a*t*t),px=left+d/10*span;box(px,y,'2 kg');arrow(px+26,y,px+56,y);text(`Trabajo acumulado: ${fmt(a*d)} J`,left,80);text('0 m',left,y+47);text('10 m',right-42,y+47);}
if(current===5){const scale=span/18,hit=6/b,vf=a*b/(a+2),cycle=hit+6/vf,t=time%cycle,x=t<hit?b*t:6+vf*(t-hit);box(left+x*scale,y,fmt(a,1));box(t<hit?left+6*scale+49:left+x*scale+49,y,'2 kg','#a9c3a0');text(t<hit?'Antes: un bloque está quieto':'Después: se mueven juntos',left,80);text(`p total = ${fmt(a*b)} kg·m/s`,left,105);}
if(current===6){const pivot=w*.2,end=pivot+b/2*w*.55,cy=h*.58;line(pivot,cy,end,cy,'#dbe6ce',8);circle(pivot,cy,12);line(pivot,cy+12,pivot-20,cy+40);line(pivot,cy+12,pivot+20,cy+40);if(a>0)arrow(end,cy-15,end,cy-15-a*3);text(`F = ${fmt(a,0)} N`,Math.min(end+12,w-105),cy-35);text(`r = ${fmt(b)} m`,pivot+20,cy+35);text('↶ Tendencia de giro',left,80);}
if(current===7){const T=2*Math.PI*Math.sqrt(a/9.81),angle=b*Math.PI/180*Math.cos(2*Math.PI*time/T),len=65+a*35,cx=w/2,cy=65,x=cx+Math.sin(angle)*len,yy=cy+Math.cos(angle)*len;line(cx,cy,cx,cy+len,'#557553');line(cx,cy,x,yy,'#e8eddc',2);circle(cx,cy,5);circle(x,yy,19);text(`θ = ${fmt(angle*180/Math.PI)}°`,left,85);text(`T ≈ ${fmt(T,2)} s`,left,108);}}
new IntersectionObserver(es=>{visible=es[0].isIntersecting},{threshold:0}).observe(canvas);document.addEventListener('visibilitychange',()=>{last=0});function tick(ts){if(last&&playing&&visible&&!document.hidden)time+=Math.min((ts-last)/1000,.05);last=ts;if(visible)draw();requestAnimationFrame(tick)}select(0);requestAnimationFrame(tick);
const quiz=[['Si la fuerza neta es cero, un cuerpo…',['Siempre está quieto.','Puede moverse con velocidad constante.','Siempre acelera.'],1,'Cero fuerza neta significa cero aceleración: el cuerpo mantiene su velocidad, que puede ser cero o distinta de cero.'],['Si duplicas la masa y mantienes la fuerza neta…',['La aceleración se reduce a la mitad.','La aceleración se duplica.','La aceleración no cambia.'],0,'Según a = F/m, al duplicar m con F constante, a se divide entre dos.'],['Sin resistencia del aire, ¿qué objeto cae primero desde la misma altura?',['El más pesado.','El más liviano.','Llegan juntos si parten del reposo.'],2,'Ambos tienen la misma aceleración gravitatoria. La masa cambia el peso, pero también la inercia en la misma proporción.'],['Al duplicar la rapidez, la energía cinética…',['Se duplica.','Se cuadruplica.','No cambia.'],1,'Ec = ½mv². Al sustituir v por 2v, aparece un factor 4.'],['En un choque donde dos bloques quedan pegados, sin fuerza externa neta…',['Se conserva el momento total.','Se conserva siempre la energía cinética.','Ambos quedan necesariamente quietos.'],0,'El momento total se conserva; parte de la energía cinética se transforma en deformación, calor y sonido.']];let qi=0,score=0,answered=false;function showQuiz(){answered=false;const q=quiz[qi];$('#quizCount').textContent=`PREGUNTA ${qi+1} / ${quiz.length}`;$('#question').textContent=q[0];$('#answers').innerHTML=q[1].map((a,i)=>`<button class="answer" data-answer="${i}">${String.fromCharCode(65+i)}. ${a}</button>`).join('');$('#feedback').textContent='';$('#next').disabled=true;$('#next').textContent=qi===4?'Ver resultado →':'Siguiente →'}$('#answers').onclick=e=>{const b=e.target.closest('button');if(!b||answered)return;answered=true;const correct=+b.dataset.answer===quiz[qi][2];if(correct)score++;b.classList.add('selected');$('#feedback').textContent=(correct?'¡Exacto! ':'La respuesta es '+String.fromCharCode(65+quiz[qi][2])+'. ')+quiz[qi][3];$('#next').disabled=false};$('#next').onclick=()=>{if(qi===5){qi=0;score=0;showQuiz()}else if(qi<4){qi++;showQuiz()}else{qi=5;$('#quizCount').textContent='RETO COMPLETADO';$('#question').textContent=`${score} de 5 respuestas correctas`;$('#answers').innerHTML='';$('#feedback').textContent='Aprender es probar, equivocarse y volver a conectar las ideas. Puedes repetir el reto o regresar al laboratorio.';$('#next').textContent='Volver a intentarlo ↺'}};showQuiz();
